{"lesson": "The previous simulator mishandled transaction rollback and the channel counter. The corrected model tracks committed state separately from uncommitted transaction state, applies rollback by discarding the transaction's changes, and computes the channel as the sum of main and other total_changes. The trigger adds one to the channel per successful write. With the corrected semantics, the calibration receipts uniquely determine put mode, trigger presence, and channel mode, so the goal is resolved.", "scope": "Disposable SQLite source with items table, put/update/delete/begin/commit/rollback actions, main and other connections, and channel/committed_count/committed_sum goals.", "source": "def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        committed = {}
        main_tx = None
        other_tx = None
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0

        def apply(conn, op, key, value):
            nonlocal main_changes, other_changes, main_total, other_total
            if op == "put":
                if put_mode == "ignore":
                    if key not in conn:
                        conn[key] = value
                        if conn is main_tx:
                            main_changes = 1
                            main_total += 1
                        else:
                            other_changes = 1
                            other_total += 1
                    else:
                        if conn is main_tx:
                            main_changes = 0
                        else:
                            other_changes = 0
                elif put_mode == "replace":
                    conn[key] = value
                    if conn is main_tx:
                        main_changes = 1
                        main_total += 1
                    else:
                        other_changes = 1
                        other_total += 1
                else:
                    conn[key] = value
                    if conn is main_tx:
                        main_changes = 1
                        main_total += 1
                    else:
                        other_changes = 1
                        other_total += 1
            elif op == "update":
                if key in conn:
                    conn[key] = value
                    if conn is main_tx:
                        main_changes = 1
                        main_total += 1
                    else:
                        other_changes = 1
                        other_total += 1
                else:
                    if conn is main_tx:
                        main_changes = 0
                    else:
                        other_changes = 0
            elif op == "delete":
                if key in conn:
                    del conn[key]
                    if conn is main_tx:
                        main_changes = 1
                        main_total += 1
                    else:
                        other_changes = 1
                        other_total += 1
                else:
                    if conn is main_tx:
                        main_changes = 0
                    else:
                        other_changes = 0

        for action in actions:
            op = action.get("op")
            conn_name = action.get("connection", "main")
            if op == "begin":
                if conn_name == "main":
                    main_tx = {}
                else:
                    other_tx = {}
            elif op == "commit":
                if conn_name == "main":
                    if main_tx is not None:
                        committed.update(main_tx)
                    main_tx = None
                else:
                    if other_tx is not None:
                        committed.update(other_tx)
                    other_tx = None
            elif op == "rollback":
                if conn_name == "main":
                    main_tx = None
                else:
                    other_tx = None
            else:
                if conn_name == "main":
                    if main_tx is not None:
                        apply(main_tx, op, action.get("key"), action.get("value"))
                    else:
                        apply(committed, op, action.get("key"), action.get("value"))
                else:
                    if other_tx is not None:
                        apply(other_tx, op, action.get("key"), action.get("value"))
                    else:
                        apply(committed, op, action.get("key"), action.get("value"))

        if channel_mode == "main_changes":
            channel = main_changes
        elif channel_mode == "main_total":
            channel = main_total
        else:
            channel = main_total + other_total
        return channel, len(committed), sum(committed.values())

    def consistent(put_mode, trigger, channel_mode):
        for receipt in history:
            actions = receipt.get("actions", [])
            observed = receipt.get("observed", {})
            channel, count, total = simulate(actions, put_mode, trigger, channel_mode)
            if channel != observed.get("channel"):
                return False
            if count != observed.get("committed_count"):
                return False
            if total != observed.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("main_changes", "main_total", "both_total"):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, trigger, channel_mode in candidates:
        channel, count, total = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            values.append(channel)
        elif goal == "committed_count":
            values.append(count)
        elif goal == "committed_sum":
            values.append(total)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}
"}
